import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {Array<{name:string,params:any,trigger:string}>} cinematicPrimitives
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?(url:string):Promise<any>}} videoLoader
 * @property {{createText(content:string, opts?:any):any}} fontAtlas
 * @property {{[key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, InstancedMesh, Matrix4, Vector3, Color, AmbientLight, DirectionalLight, AdditiveBlending } = ctx.THREE;

  const root = new Group();

  // -----------------------------------------------------------------
  // 1️⃣  Text
  // -----------------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textZ = 0.5; // hero baseline Z
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 48,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: (item.typography?.letterSpacing ?? 0) * (item.typography?.fontSize ?? 48),
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // positioning according to role
    let y = 0;
    if (item.role === 'hero') {
      y = 0.5; // baseline 0.5 units above center
      txt.position.set(0, y, textZ);
    } else if (item.role === 'subhead') {
      y = 0.5 - 0.75; // 0.75 units below hero baseline
      txt.position.set(0, y, textZ);
    } else if (item.role === 'caption') {
      y = -2.25; // 2.25 units below center
      txt.position.set(0, y, textZ);
    } else {
      // default fallback
      txt.position.set(0, 0, textZ);
    }
    root.add(txt);
  }

  // -----------------------------------------------------------------
  // 2️⃣  Lights
  // -----------------------------------------------------------------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(2, 3, 4);
  root.add(key);

  const rim = new DirectionalLight(0xffffff, 0.8);
  rim.position.set(-2, -1, -3);
  root.add(rim);

  // -----------------------------------------------------------------
  // 3️⃣  Particles
  // -----------------------------------------------------------------
  const TOTAL = 1200;
  const CORE_COUNT = 90;
  const OUTER_COUNT = TOTAL - CORE_COUNT;

  const geo = new ctx.THREE.IcosahedronGeometry(0.012, 0);

  // Outer particles material
  const outerMat = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'),
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0.9,
    depthWrite: false,
  });

  // Core particles material (additive)
  const coreMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0.5,
    transparent: true,
    opacity: 1.0,
    depthWrite: false,
  });
  coreMat.blending = AdditiveBlending;

  const outerMesh = new InstancedMesh(geo, outerMat, OUTER_COUNT);
  const coreMesh = new InstancedMesh(geo, coreMat, CORE_COUNT);

  // Store original positions for drift animation
  const outerPositions = [];
  const outerPhases = [];
  const corePositions = [];
  const corePhases = [];

  const tempPos = new Vector3();
  const tempMat = new Matrix4();

  // Helper: random in range
  const randRange = (min, max) => Math.random() * (max - min) + min;

  // Populate outer instances (ellipsoidal shell 6×4×5 centered at (0,0,-1.5))
  for (let i = 0; i < OUTER_COUNT; i++) {
    const x = randRange(-3, 3);
    const y = randRange(-2, 2);
    const z = randRange(-2.5, 2.5) - 1.5; // apply center offset
    tempPos.set(x, y, z);
    outerPositions.push(tempPos.clone());
    outerPhases.push(randRange(0, Math.PI * 2));
    tempMat.compose(tempPos, new ctx.THREE.Quaternion(), new Vector3(1, 1, 1));
    outerMesh.setMatrixAt(i, tempMat);
  }

  // Populate core instances (sphere radius 0.5 at origin)
  for (let i = 0; i < CORE_COUNT; i++) {
    const phi = Math.acos(randRange(-1, 1));
    const theta = randRange(0, Math.PI * 2);
    const r = Math.cbrt(Math.random()) * 0.5; // uniform in sphere
    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);
    tempPos.set(x, y, z);
    corePositions.push(tempPos.clone());
    corePhases.push(randRange(0, Math.PI * 2));
    tempMat.compose(tempPos, new ctx.THREE.Quaternion(), new Vector3(1, 1, 1));
    coreMesh.setMatrixAt(i, tempMat);
  }

  outerMesh.instanceMatrix.needsUpdate = true;
  coreMesh.instanceMatrix.needsUpdate = true;

  root.add(outerMesh);
  root.add(coreMesh);

  // -----------------------------------------------------------------
  // 4️⃣  Drift animation (ambient orbit of each particle)
  // -----------------------------------------------------------------
  const DRIFT_FREQ = 0.05; // Hz
  const DRIFT_AMPL = 0.04; // units

  const driftUpdate = () => {
    const t = performance.now() * 0.001 * Math.PI * 2 * DRIFT_FREQ; // angular time
    // outer
    for (let i = 0; i < OUTER_COUNT; i++) {
      const phase = outerPhases[i];
      const base = outerPositions[i];
      const offset = Math.sin(t + phase) * DRIFT_AMPL;
      tempPos.set(base.x + offset, base.y + offset, base.z);
      tempMat.compose(tempPos, new ctx.THREE.Quaternion(), new Vector3(1, 1, 1));
      outerMesh.setMatrixAt(i, tempMat);
    }
    // core
    for (let i = 0; i < CORE_COUNT; i++) {
      const phase = corePhases[i];
      const base = corePositions[i];
      const offset = Math.sin(t + phase) * DRIFT_AMPL;
      tempPos.set(base.x + offset, base.y + offset, base.z);
      tempMat.compose(tempPos, new ctx.THREE.Quaternion(), new Vector3(1, 1, 1));
      coreMesh.setMatrixAt(i, tempMat);
    }
    outerMesh.instanceMatrix.needsUpdate = true;
    coreMesh.instanceMatrix.needsUpdate = true;
  };

  const driftTicker = gsap.ticker.add(driftUpdate);

  // -----------------------------------------------------------------
  // 5️⃣  Core emissive pulse
  // -----------------------------------------------------------------
  const pulse = { intensity: 1.5 };
  const corePulseTl = gsap.to(pulse, {
    intensity: 1.8,
    duration: 5, // 0.1 Hz -> period 10s, half cycle 5s
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut',
    onUpdate: () => {
      coreMat.emissiveIntensity = pulse.intensity;
    },
  });

  // -----------------------------------------------------------------
  // 6️⃣  Cinematic primitive (particle‑emerge)
  // -----------------------------------------------------------------
  const primitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name && ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](root, prim.params ?? {});
        primitives.push(result);
      }
    }
  }

  // -----------------------------------------------------------------
  // 7️⃣  Cleanup
  // -----------------------------------------------------------------
  root.userData.handlers = {}; // no interaction handlers required

  root.userData.cleanup = () => {
    // Dispose meshes & materials
    outerMesh.geometry.dispose();
    outerMat.dispose();
    coreMesh.geometry.dispose();
    coreMat.dispose();

    // Stop GSAP ticker & timelines
    gsap.ticker.remove(driftUpdate);
    driftTicker && gsap.ticker.remove(driftUpdate);
    corePulseTl && corePulseTl.kill();

    // Clean primitives
    for (const p of primitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Remove lights
    root.remove(ambient);
    root.remove(key);
    root.remove(rim);
  };

  return root;
}
